"""Build a privacy-conscious static GitHub Pages job board."""
import csv
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SITE = ROOT / "site"
SITE.mkdir(parents=True, exist_ok=True)
CSV_PATH = ROOT / "vagas_para_revisar.csv"
FIELDS = ("empresa", "titulo", "nivel", "local", "modalidade", "area", "pontuacao", "url")
if CSV_PATH.exists():
    with CSV_PATH.open(encoding="utf-8-sig", newline="") as handle:
        rows = list(csv.DictReader(handle))
else:
    rows = []
public = [{key: row.get(key, "") for key in FIELDS} for row in rows]
(SITE / "vagas.json").write_text(json.dumps(public, ensure_ascii=False, indent=2), encoding="utf-8")
(SITE / "index.html").write_text("<!doctype html>\n<html lang=\"pt-BR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#0b1020\"><meta name=\"description\" content=\"Descubra oportunidades de estágio e júnior em tecnologia em São Paulo e remoto.\"><title>JobHunter AI — Seu próximo passo começa aqui</title>\n<style>\n:root{color-scheme:dark;--bg:#090e1a;--panel:#111b2d;--panel2:#17243a;--line:#29374c;--muted:#9caec7;--text:#f1f6ff;--accent:#72e2bb;--blue:#8db9ff}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 70% -15%,#1c3652 0%,transparent 48%),var(--bg);font:15px/1.55 system-ui,-apple-system,Segoe UI,sans-serif;color:var(--text)}a{color:inherit;text-decoration:none}button,input,select{font:inherit}button,select{cursor:pointer}.shell{max-width:1180px;margin:auto;padding:0 24px}.nav{height:76px;border-bottom:1px solid #ffffff13;display:flex;align-items:center;justify-content:space-between}.brand{font-size:19px;font-weight:850;letter-spacing:-.6px}.brand span{color:var(--accent)}.nav-right{display:flex;gap:14px;align-items:center;color:var(--muted);font-size:13px}.nav-right a:hover{color:white}.dot{width:8px;height:8px;background:var(--accent);border-radius:50%;box-shadow:0 0 15px var(--accent);display:inline-block;margin-right:7px}.hero{padding:70px 0 44px;max-width:820px}.eyebrow{display:inline-block;border:1px solid #4d816f;background:#15352e;color:#a5f7d5;border-radius:30px;padding:7px 12px;font-size:12px;font-weight:700;letter-spacing:.4px}.hero h1{font-size:clamp(37px,5.3vw,65px);line-height:1.08;letter-spacing:-2.5px;margin:22px 0}.hero h1 em{color:var(--accent);font-style:normal}.hero p{color:var(--muted);font-size:17px;max-width:620px;margin:0}.metrics{display:flex;gap:12px;flex-wrap:wrap;margin:36px 0}.metric{background:#ffffff08;border:1px solid var(--line);border-radius:14px;padding:14px 20px;min-width:150px}.metric strong{display:block;font-size:24px}.metric small{color:var(--muted)}.workspace{display:grid;grid-template-columns:255px minmax(0,1fr);gap:24px;padding-bottom:80px}.sidebar,.results{min-width:0}.filter-panel{border:1px solid var(--line);background:#10192a;border-radius:18px;padding:22px;position:sticky;top:20px}.filter-panel h2{font-size:16px;margin:0 0 22px}.field{display:block;margin:0 0 18px}.field label{display:block;color:#d4e0ef;font-size:13px;font-weight:700;margin-bottom:8px}input,select{width:100%;background:#0a1322;border:1px solid #34445a;color:white;border-radius:10px;padding:12px;outline:none}input:focus,select:focus{border-color:var(--accent);box-shadow:0 0 0 3px #72e2bb20}input::placeholder{color:#7e91a8}.reset{border:1px solid #34445a;background:transparent;color:#c8d8e9;border-radius:9px;padding:10px;width:100%}.reset:hover{border-color:var(--accent)}.result-head{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:0 0 18px}.result-head h2{margin:0;font-size:22px;letter-spacing:-.5px}.result-head p{color:var(--muted);font-size:13px;margin:4px 0 0}.result-head select{max-width:230px}.cards{display:grid;gap:14px}.job{border:1px solid var(--line);background:linear-gradient(135deg,#152239,#101a2a);padding:23px;border-radius:17px;transition:transform .18s,border-color .18s}.job:hover{transform:translateY(-2px);border-color:#51776f}.job-top{display:flex;justify-content:space-between;gap:12px}.company{color:var(--accent);font-size:13px;font-weight:700}.job h3{font-size:20px;letter-spacing:-.4px;line-height:1.3;margin:7px 0 13px}.score{flex-shrink:0;border-radius:12px;background:#14392e;color:#a6f5d4;padding:9px 11px;font-weight:800;font-size:14px;height:fit-content}.score small{display:block;font-size:10px;font-weight:500;color:#a8d7c5}.tags{display:flex;flex-wrap:wrap;gap:7px}.tag{background:#ffffff0b;border:1px solid #34445a;border-radius:8px;padding:5px 9px;color:#b8c9df;font-size:12px}.job-bottom{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:20px;padding-top:16px;border-top:1px solid #ffffff14}.job-bottom small{color:var(--muted)}.apply{background:var(--accent);color:#07231b;padding:10px 15px;border-radius:9px;font-weight:800;font-size:13px}.apply:hover{background:#a5f4d8}.empty{border:1px dashed #40516b;border-radius:18px;padding:54px 20px;text-align:center;background:#ffffff04}.empty .emoji{font-size:36px}.empty h3{font-size:20px;margin:10px 0}.empty p{color:var(--muted);max-width:460px;margin:0 auto 18px}.footer{border-top:1px solid #ffffff15;padding:26px 0;color:var(--muted);font-size:12px}.footer .shell{display:flex;justify-content:space-between;gap:15px;flex-wrap:wrap}@media(max-width:760px){.shell{padding:0 17px}.hero{padding:48px 0 24px}.hero h1{letter-spacing:-1.4px}.workspace{grid-template-columns:1fr}.filter-panel{position:static}.filter-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 12px}.result-head{align-items:flex-start;flex-direction:column}.result-head select{max-width:none}.nav-right .label{display:none}.job{padding:18px}}@media(max-width:400px){.filter-grid{grid-template-columns:1fr}.job-bottom{align-items:flex-start;flex-direction:column}.apply{width:100%;text-align:center}}\n</style></head><body>\n<div class=\"shell\"><nav class=\"nav\" aria-label=\"Principal\"><a class=\"brand\" href=\"./\">✦ JobHunter<span>AI</span></a><div class=\"nav-right\"><span><span class=\"dot\"></span><span class=\"label\">Painel de oportunidades</span></span><a href=\"https://github.com/JoaoVictorAAbreu-Dev/jobhunter-ai\" target=\"_blank\" rel=\"noopener noreferrer\">GitHub ↗</a></div></nav>\n<header class=\"hero\"><span class=\"eyebrow\">✦ OPORTUNIDADES EM TECNOLOGIA</span><h1>Sua próxima oportunidade <em>começa aqui.</em></h1><p>Encontre vagas de estágio e júnior em São Paulo, região metropolitana e remoto. Explore oportunidades e acesse os anúncios oficiais.</p><div class=\"metrics\"><div class=\"metric\"><strong id=\"total\">—</strong><small>Vagas encontradas</small></div><div class=\"metric\"><strong id=\"companies\">—</strong><small>Empresas</small></div><div class=\"metric\"><strong id=\"remote\">—</strong><small>Oportunidades remotas</small></div></div></header>\n<section class=\"workspace\" aria-label=\"Oportunidades\"><aside class=\"sidebar\"><div class=\"filter-panel\"><h2>⚙️ Filtrar oportunidades</h2><div class=\"filter-grid\"><div class=\"field\"><label for=\"q\">Buscar vaga ou empresa</label><input id=\"q\" type=\"search\" placeholder=\"Ex.: React, Java, estágio\"></div><div class=\"field\"><label for=\"area\">Área</label><select id=\"area\"><option value=\"\">Todas as áreas</option></select></div><div class=\"field\"><label for=\"level\">Nível</label><select id=\"level\"><option value=\"\">Todos os níveis</option></select></div><div class=\"field\"><label for=\"mode\">Modalidade</label><select id=\"mode\"><option value=\"\">Todas as modalidades</option></select></div></div><button id=\"clear\" class=\"reset\" type=\"button\">Limpar filtros ↺</button></div></aside><div class=\"results\"><div class=\"result-head\"><div><h2>Vagas para explorar</h2><p id=\"count\" role=\"status\" aria-live=\"polite\">Carregando oportunidades...</p></div><select id=\"sort\" aria-label=\"Ordenar vagas\"><option value=\"score\">Maior compatibilidade</option><option value=\"company\">Empresa (A–Z)</option><option value=\"title\">Cargo (A–Z)</option></select></div><div id=\"jobs\" class=\"cards\"></div></div></section></div>\n<footer class=\"footer\"><div class=\"shell\"><span>© JobHunter AI · Projeto independente</span><span>As candidaturas são realizadas exclusivamente nos sites oficiais. Nenhum envio automático.</span></div></footer>\n<script>\nconst $=id=>document.getElementById(id), controls=['q','area','level','mode','sort'];let all=[],loadError=false;\nconst clean=x=>String(x??'').trim(), score=x=>{const n=Number(clean(x.pontuacao).replace(',','.'));return Number.isFinite(n)?n:0};\nfunction optionize(id,key){const el=$(id);[...new Set(all.map(x=>clean(x[key])).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'pt-BR')).forEach(v=>{const o=document.createElement('option');o.value=v;o.textContent=v;el.append(o)})}\nfunction tag(value){const t=document.createElement('span');t.className='tag';t.textContent=value;return t}\nfunction draw(){const query=$('q').value.toLocaleLowerCase('pt-BR'),area=$('area').value,level=$('level').value,mode=$('mode').value;const found=all.filter(x=>(!area||x.area===area)&&(!level||x.nivel===level)&&(!mode||x.modalidade===mode)&&[x.titulo,x.empresa,x.local,x.area].join(' ').toLocaleLowerCase('pt-BR').includes(query));const order=$('sort').value;found.sort((a,b)=>order==='score'?score(b)-score(a):clean(a[order==='company'?'empresa':'titulo']).localeCompare(clean(b[order==='company'?'empresa':'titulo']),'pt-BR'));$('count').textContent=found.length+' oportunidade'+(found.length===1?'':'s')+' encontrada'+(found.length===1?'':'s');$('jobs').replaceChildren();if(!found.length){const e=document.createElement('div');e.className='empty';const ico=document.createElement('div');ico.className='emoji';ico.textContent=loadError?'⚠️':'🔎';const h=document.createElement('h3');h.textContent=loadError?'Não foi possível carregar as vagas':all.length?'Nenhuma vaga corresponde aos filtros':'Ainda não há vagas disponíveis';const p=document.createElement('p');p.textContent=loadError?'Tente atualizar a página.':all.length?'Experimente remover algum filtro ou buscar outro termo.':'Configure as fontes de vagas Greenhouse/Lever no repositório e execute o workflow para atualizar este painel.';e.append(ico,h,p);if(all.length){const b=document.createElement('button');b.className='reset';b.style.maxWidth='190px';b.textContent='Limpar filtros';b.onclick=clear;e.append(b)}$('jobs').append(e);return}for(const x of found){const article=document.createElement('article');article.className='job';const top=document.createElement('div');top.className='job-top';const titleWrap=document.createElement('div');const company=document.createElement('div');company.className='company';company.textContent=clean(x.empresa)||'Empresa não informada';const h=document.createElement('h3');h.textContent=clean(x.titulo)||'Oportunidade';titleWrap.append(company,h);top.append(titleWrap);if(clean(x.pontuacao)){const s=document.createElement('div');s.className='score';s.textContent=clean(x.pontuacao);const small=document.createElement('small');small.textContent='compatibilidade';s.append(small);top.append(s)}const tags=document.createElement('div');tags.className='tags';[x.local,x.nivel,x.modalidade,x.area].map(clean).filter(Boolean).forEach(v=>tags.append(tag(v)));const bottom=document.createElement('div');bottom.className='job-bottom';const note=document.createElement('small');note.textContent='Confira os requisitos no anúncio oficial';bottom.append(note);try{const url=new URL(clean(x.url));if(['https:','http:'].includes(url.protocol)){const a=document.createElement('a');a.className='apply';a.href=url.href;a.target='_blank';a.rel='noopener noreferrer';a.textContent='Ver vaga ↗';bottom.append(a)}}catch{}article.append(top,tags,bottom);$('jobs').append(article)}}\nfunction clear(){['q','area','level','mode'].forEach(id=>$(id).value='');draw()}$('clear').addEventListener('click',clear);controls.forEach(id=>$(id).addEventListener(id==='q'?'input':'change',draw));fetch('./vagas.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error(r.status);return r.json()}).then(data=>{all=Array.isArray(data)?data:[];$('total').textContent=all.length;$('companies').textContent=new Set(all.map(x=>x.empresa).filter(Boolean)).size;$('remote').textContent=all.filter(x=>/remot|remote|home.office/i.test(clean(x.modalidade)+' '+clean(x.local))).length;optionize('area','area');optionize('level','nivel');optionize('mode','modalidade');draw()}).catch(()=>{loadError=true;all=[];['total','companies','remote'].forEach(id=>$(id).textContent='—');draw()});\n</script></body></html>", encoding="utf-8")
print(f"Site gerado com {len(public)} vagas públicas")
